param([switch]$SkipBuild,[switch]$SkipTests)
$ErrorActionPreference='Stop'
$taskRoot=Split-Path $PSScriptRoot -Parent
if(!$SkipBuild){& (Join-Path $PSScriptRoot 'build.ps1')}
if(!$SkipTests){& (Join-Path $PSScriptRoot 'test.ps1') -SkipBuild}
# Packages use the reviewed tracked source, not directory copies that can
# silently include credentials, generated bytecode or other local files.
if(!(Get-Command git -ErrorAction SilentlyContinue)){throw 'Publishing requires Git and a reviewed source checkout.'}
$taskGitRoot=& git -C $taskRoot rev-parse --show-toplevel
if($LASTEXITCODE -or [IO.Path]::GetFullPath($taskGitRoot) -ne [IO.Path]::GetFullPath($taskRoot)){throw 'Publish from the project Git checkout after reviewing its tracked files.'}
$taskSourceFiles=@(& git -C $taskRoot -c core.quotepath=false ls-files)
if($LASTEXITCODE -or !$taskSourceFiles.Count){throw 'No tracked source is available to package.'}
$taskName='WinDroidCapture-0.3.0-dev-win-x64-'+(Get-Date -Format 'yyyyMMdd-HHmmss')
$taskDist=Join-Path $taskRoot 'dist'
$taskPackage=Join-Path $taskDist $taskName
if(Test-Path -LiteralPath $taskPackage){throw 'Publish destination exists. Nothing was replaced.'}
New-Item -ItemType Directory -Path $taskPackage | Out-Null
foreach($taskFile in @('WinDroidCapture.exe','awm-media-host.exe','scrcpy-awm.exe','scrcpy-server-awm','awm-camera-server.json','awm-camera-source.dll','awm-camera-control.exe','awm-microphone-install.exe','awm-native-receiver.exe','awm-capture-smoke.exe')){
    Copy-Item -LiteralPath (Join-Path $taskRoot "build-native\$taskFile") -Destination $taskPackage
}
New-Item -ItemType Directory -Path (Join-Path $taskPackage 'scripts'),(Join-Path $taskPackage 'source') | Out-Null
Copy-Item -LiteralPath (Join-Path $taskRoot 'licenses') -Destination $taskPackage -Recurse
foreach($taskFile in $taskSourceFiles){
    $taskTarget=Join-Path (Join-Path $taskPackage 'source') $taskFile
    New-Item -ItemType Directory -Path (Split-Path $taskTarget -Parent) -Force | Out-Null
    Copy-Item -LiteralPath (Join-Path $taskRoot $taskFile) -Destination $taskTarget
}
Copy-Item -LiteralPath (Join-Path $PSScriptRoot 'run.ps1'),(Join-Path $PSScriptRoot 'install-outputs.ps1'),(Join-Path $PSScriptRoot 'measure-timing.ps1'),(Join-Path $PSScriptRoot 'plot-timing.py') -Destination (Join-Path $taskPackage 'scripts')
# The unsigned, never-kernel-tested driver remains a source-only deliverable.
# Do not attach it as if it were an installable Windows microphone.
$taskReadme=@'
# WinDroid Capture — Windows development snapshot

![Phone Lens](source/src/assets/windroid-capture-64.png)

**Camera and screen video; phone microphone unavailable.** This unsigned
development package includes the owned camera/source, controller and modified
scrcpy server. Install the matching official scrcpy 5.0.1 runtime separately.
Unsigned kernel driver binaries are omitted; driver source is under source/drivers.

[Setup](source/docs/QUICKSTART.md) · [Complete README](source/README.md) ·
[Test report](source/TEST_REPORT.md) · [Notices](source/THIRD_PARTY_NOTICES.md)

```powershell
.\scripts\install-outputs.ps1 -Camera
.\scripts\run.ps1 -ScrcpyFolder 'C:\path\scrcpy-win64-v5.0.1'
```

Select Audio: Off for video tests. In Discord choose
Android Webcam Camera (Windows Virtual Camera). Own microphone signing/kernel
validation, receiver-sharing and final smoothness checks remain incomplete.
SHA256SUMS.txt covers the included files; third-party runtime DLLs, raw evidence,
credentials, user settings, downloaded tools and development caches are excluded.
'@
$taskReadme | Set-Content -LiteralPath (Join-Path $taskPackage 'README.md') -Encoding UTF8
Copy-Item -LiteralPath (Join-Path $taskRoot 'build-native\deps\native-dependencies.json') -Destination $taskPackage
$taskHashes=Get-ChildItem -LiteralPath $taskPackage -File -Recurse | ForEach-Object { $taskHash=Get-FileHash -LiteralPath $_.FullName -Algorithm SHA256; $taskHash.Hash.ToLowerInvariant()+'  '+$_.FullName.Substring($taskPackage.Length+1) }
$taskHashes | Set-Content -LiteralPath (Join-Path $taskPackage 'SHA256SUMS.txt') -Encoding UTF8
Compress-Archive -LiteralPath $taskPackage -DestinationPath (Join-Path $taskDist ($taskName+'.zip'))
Write-Output "Windows development package: $taskPackage"
Write-Output 'Run scripts\run.ps1 with the official matching scrcpy distribution. Own microphone is source-only; unsigned kernel binaries are omitted.'
